    userService.getAllUserInfos(true, widgetContext.pageLink(10000,0)).subscribe(users => {
        if(users && users.data && users.data.length){
            users.data.forEach(x=>{
                vm.users.push(x);
            });
        }
    });

    vm.alarmInfoFormGroup = vm.fb.group({
        name: [null, [vm.validators.required]],
        description: [null],
        isActive: false,
        devices: [null]
    });

    vm.alarmUsersFormGroup = vm.fb.group({
        users: [null],
        phone: false,
        email: false,
        application: false
    });

    vm.cancel = function() {
        vm.dialogRef.close(null);
    };

    vm.save = function() {
        let {name, description, isActive, devices} = vm.alarmInfoFormGroup.value;
        let {users, phone, email, application} = vm.alarmUsersFormGroup.value;

        let payload = {
            name,
            type: "alertProfile"
        };

        let config = {
            description: description,
            isActive: isActive,
            phone: phone,
            email: email,
            application: application
        }

        assetService.saveAsset(payload).subscribe(response => {
            attributeService.saveEntityAttributes(response.id, "SERVER_SCOPE", [{key: "alarmConfig", value: config}]).subscribe(()=>{
                devices.forEach(x=>{
                    entityRelationService.saveRelation({
                        from: response.id,
                        to: x.id,
                        type: 'AlarmConfigToDevice',
                        typeGroup: 'COMMON'
                    }).subscribe();
                })
                users.forEach(x=>{
                    entityRelationService.saveRelation({
                        from: response.id,
                        to: x.id,
                        type: 'AlarmConfigToInformingUser',
                        typeGroup: 'COMMON'
                    }).subscribe();
                })
                widgetContext.updateAliases();
                vm.dialogRef.close(null);
                widgetContext.showSuccessToast(`Device config was created successfully!`, 4000, "bottom", "left", "layout");
            })
        });
    };
}

let controller = widgetContext.$scope.ctx.stateController;
let params = controller.getStateParams();
let statesArray = params['statesArray'];
let prevState = statesArray[statesArray.length-2].stateId;

let newParams = {
    stateId: prevState,
    mode: params['mode'],
    enabled: params['enabled']
}

widgetContext.stateController.navigatePrevState(0);
widgetContext.$scope.ctx.stateController.updateState('default', newParams);
